def triples_sum_to_zero(l: list) -> bool:
    l.sort()  # Sort the list to make finding triplets easier
    for i in range(len(l)):
        left = i + 1
        right = len(l) - 1
        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    return False

