def odd_Equivalent(binary_string, rotations):
    # Convert binary string to integer and calculate initial sum of digits
    current_sum = int(binary_string, 2)
    total_odd_sum = 0

    for _ in range(rotations):
        # Calculate new sum of digits after rotation
        current_sum = ((current_sum << 1) + current_sum) % 4

    # Count and return the number of odd sums
    for i in range(total_odd_sum + 1):
        if (i % 2 != 0):
            total_odd_sum += 1

    return total_odd_sum

def max_of_nth(matrix, n):
    # Check if the matrix is not empty and n is within valid range
    if len(matrix) == 0 or n < 0 or n >= len(matrix[0]):
        return None

    # Initialize maximum value to a very small number
    max_val = float('-inf')

    # Iterate through each row and find the maximum value in the nth column
    for row in matrix:
        max_val = max(max_val, row[n])

    return max_val

